const w = $input.first()?.json;
const transcript = String(w?.text || '').trim();
if (!transcript || transcript.length < 20) return [{ json: { _error: 'WHISPER_EMPTY', _status: 502, _details: 'Whisper devolvio transcripcion vacia o muy corta' } }];
return [{ json: { transcript_raw: transcript, transcript_source: 'whisper-1', audio_duration_seconds: w?.duration || null } }];

// Conver. ambas ramas. Por gotcha 6.3 usamos isExecuted antes de tocar nodos.
const sess = $('Decode JWT + Body').first().json;
const proj = $('Load Project + Planning').first().json;
const input = $input.first().json;
if (input._error) return [{ json: input }];

const transcript = String(input.transcript_raw || '').trim();
if (!transcript) return [{ json: { _error: 'NO_TRANSCRIPT', _status: 502, _details: 'no se obtuvo transcripcion' } }];

const phases = Array.isArray(proj.planning_phases) ? proj.planning_phases : [];
const planningSummary = phases.length
  ? phases.map((ph,i) => {
      const titulo = ph.titulo || ph.name || ph.nombre || ph.title || '(fase sin titulo)';
      const fIni = ph.fecha_inicio || ph.start_date || ph.start || '?';
      const fFin = ph.fecha_fin || ph.end_date || ph.end || '?';
      const gremios = Array.isArray(ph.gremios) ? ph.gremios.join(', ') : (ph.gremio || '?');
      return `${i+1}. [${gremios}] ${titulo} (${fIni} -> ${fFin})`;
    }).join('\n')
  : '(no hay planning vigente cargado para este proyecto)';

const photos = sess.photos_urls || [];
const photosBlock = photos.length
  ? photos.map((u,i) => `${i+1}. ${u}`).join('\n')
  : '(sin fotos aportadas)';

const gremiosValidos = ['albanileria','fontaneria','electricidad','carpinteria','pintura','cubiertas','estructura','climatizacion','aislamiento','demolicion','otros'];

const systemPrompt = `Eres agent_acta_obra. El arquitecto ha grabado un audio durante una visita a una obra de reforma. Recibes la transcripcion bruta y la conviertes en un acta profesional estructurada.\n\nDevuelve SOLO JSON valido con la forma EXACTA:\n{\n  observaciones: [\n    { gremio: string, texto: string, tipo: 'incidencia'|'avance'|'pendiente', fotos_referenciadas: number[] }\n  ],\n  acuerdos: string,\n  proxima_visita_prevista: string|null\n}\n\nREGLAS:\n- gremio debe ser uno de: ${gremiosValidos.join(', ')}.\n- Cada observacion en 1-2 frases concisas, profesionales.\n- tipo: 'incidencia'=problema detectado, 'avance'=trabajo completado/progreso OK, 'pendiente'=tarea por hacer.\n- fotos_referenciadas: indices 1-based de fotos mencionadas (ej. 'la foto 1', 'esta humedad'). [] si no menciona.\n- acuerdos: resumen plano de los acuerdos tomados durante la visita (cliente, gremios, arquitecto). String vacio si no hay.\n- proxima_visita_prevista: ISO 8601 (YYYY-MM-DD o YYYY-MM-DDTHH:MM:SS) si la transcripcion menciona fecha/hora. null si no.\n- NO inventes datos que no esten en la transcripcion. Si el arquitecto no menciona algo, no lo pongas.\n- Cruza con el PLANNING vigente para detectar avances/retrasos sobre tareas planificadas, pero SOLO si el arquitecto los menciona.`;

const userPrompt = `PROYECTO: ${proj.name}\nFASE: ${proj.current_phase}\nMUNICIPIO: ${proj.location_city || '?'}\n\nPLANNING VIGENTE (v${proj.plan_version || '?'}, tareas activas):\n${planningSummary}\n\nFOTOS DISPONIBLES (indices 1..${photos.length}):\n${photosBlock}\n\nTRANSCRIPCION AUDIO (fuente: ${input.transcript_source}${input.audio_duration_seconds ? ', ' + input.audio_duration_seconds + 's' : ''}):\n"""\n${transcript}\n"""\n\nGenera el acta estructurada en JSON.`;

return [{ json: {
  ...sess,
  project_id: proj.id,
  project_name: proj.name,
  current_phase: proj.current_phase,
  client_name: proj.client_name,
  client_email: proj.client_email,
  plan_id: proj.plan_id,
  plan_version: proj.plan_version,
  transcript_raw: transcript,
  transcript_source: input.transcript_source,
  audio_duration_seconds: input.audio_duration_seconds,
  llm_payload: {
    model: 'gpt-4o-mini',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.2,
    max_tokens: 1800,
    response_format: { type: 'json_object' }
  }
}}];

