parameters.jsCode:
const llm = $input.first()?.json;
const ctx = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message } }];
}
const gremiosValidos = ['albanileria','fontaneria','electricidad','carpinteria','pintura','cubiertas','estructura','climatizacion','aislamiento','demolicion','otros'];
const rawObs = Array.isArray(parsed.observaciones) ? parsed.observaciones.slice(0, 40) : [];
const obs = [];
for (const o of rawObs) {
  const texto = String(o.texto || '').slice(0, 600);
  if (!texto) continue;
  const grRaw = String(o.gremio || '').toLowerCase();
  const tiRaw = String(o.tipo || '').toLowerCase();
  const fotos = Array.isArray(o.fotos_referenciadas) ? o.fotos_referenciadas.map(n => Number(n)).filter(n => Number.isInteger(n) && n > 0) : [];
  obs.push({
    gremio: gremiosValidos.includes(grRaw) ? grRaw : 'otros',
    texto,
    tipo: ['incidencia','avance','pendiente'].includes(tiRaw) ? tiRaw : 'pendiente',
    fotos_referenciadas: fotos
  });
}
const acuerdos = String(parsed.acuerdos || '').slice(0, 4000);
const proxima = parsed.proxima_visita_prevista && /^\d{4}-\d{2}-\d{2}/.test(String(parsed.proxima_visita_prevista)) ? String(parsed.proxima_visita_prevista) : null;
const usage = llm?.usage || {};
return [{ json: {
  ...ctx,
  transcript_categorized: { observaciones: obs, acuerdos, proxima_visita_prevista: proxima },
  observations: obs,
  acuerdos,
  proxima_visita_prevista: proxima,
  observation_count: obs.length,
  model: llm?.model || 'gpt-4o-mini',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0
}}];

