  tenant_id, project_id, visit_date, audio_url, audio_duration_seconds,
  transcript_raw, transcript_categorized, observations, photos, acuerdos,
  proxima_visita_prevista, status
) VALUES (
  $1::uuid, $2::uuid, COALESCE($3::timestamptz, now()), $4, $5::int,
  $6, $7::jsonb, $8::jsonb, $9::jsonb, $10,
  $11::timestamptz, 'draft'
)
RETURNING id, visit_date, status, created_at;

